CREATE OR REPLACE FUNCTION public.append_approved_connecteam_pro() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE next_priority integer; BEGIN IF NEW.paperwork_complete AND NOT NEW.is_test AND NEW.service_line IN ('cleaning','lawn','detailing') AND NEW.connecteam_user_id NOT IN (31157941,31157945) AND NOT EXISTS(SELECT 1 FROM public.jobber_service_pro_pool WHERE service_line=NEW.service_line AND connecteam_user_id=NEW.connecteam_user_id) THEN PERFORM pg_advisory_xact_lock(hashtext('connecteam-pool:'||NEW.service_line)); SELECT coalesce(max(priority),0)+1 INTO next_priority FROM public.jobber_service_pro_pool WHERE service_line=NEW.service_line; INSERT INTO public.jobber_service_pro_pool(service_line,connecteam_user_id,pro_name,priority,active) SELECT NEW.service_line,NEW.connecteam_user_id,NEW.name,next_priority,true WHERE NOT EXISTS(SELECT 1 FROM public.jobber_service_pro_pool WHERE service_line=NEW.service_line AND connecteam_user_id=NEW.connecteam_user_id); END IF; RETURN NEW; END; $$;
CREATE TRIGGER paperwork_assignment_after_approval AFTER UPDATE OF paperwork_complete ON public.pro_pay_profiles FOR EACH ROW EXECUTE FUNCTION public.append_approved_connecteam_pro();